def build_agent(sandbox):
    # Create a single wide and tall beam for buoyancy and stability
    main_beam = sandbox.add_beam(x=5.0, y=1.0, width=2.0, height=2.0, density=1.0)
    sandbox.set_material_properties(main_beam, restitution=0.05)
    return main_beam

last_thrust_step = -1

def agent_action(sandbox, agent_body, step_count):
    global last_thrust_step
    if agent_body is None or not agent_body.active:
        return
    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0
    if front_x >= target_x + 0.1:
        # Stop the vehicle
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return
    # Check if in deep channel
    in_deep_channel = (16.5 <= front_x <= 19.5)
    if in_deep_channel:
        # Apply lift force to counteract reduced buoyancy
        sandbox.apply_force(agent_body, 0, 400, step_count=step_count)
    else:
        # Apply thrust with cooldown
        if step_count >= last_thrust_step + 3:
            # Apply maximum allowed thrust
            sandbox.apply_force(agent_body, 520, 0, step_count=step_count)
            last_thrust_step = step_count

